from abc import abstractmethod
class Service:
    @abstractmethod
    def abstract(self): pass
    @staticmethod
    def static(): pass
    @classmethod
    def cls(cls): pass
    def instance(self): pass

from typing import overload
@overload
def call(x: int) -> int: ...
@overload
def call(x: str) -> str: ...
def call(x):
    return x

def calculate(x: int):
    return x
